from datetime import datetime, timedelta, timezone

class Time:
    def __init__(self, timestamp=None, tz=None):
        if isinstance(timestamp, datetime):
            self.timestamp = timestamp
            self.tz = tz
        else:
            self.timestamp = datetime.fromtimestamp(timestamp, tz)
            self.tz = tz

    def __repr__(self):
        return f"{self.timestamp.strftime('%Y-%m-%d %H:%M:%S%Z') if self.tz else self.timestamp.strftime('%Y-%m-%d %H:%M:%S')} tz={self.tz}"

    def __eq__(self, other):
        if not isinstance(other, Time):
            return False
        return self.timestamp == other.timestamp and self.tz == other.tz

    @staticmethod
    def hydrate_from_json(json_data):
        if 'timestamp' not in json_data or 'tz' not in json_data:
            raise ValueError("JSON data must contain 'timestamp' and 'tz' keys")
        return Time(json_data['timestamp'], timezone(json_data['tz']))
