    if not keys:
        return {field: getattr(self, field) for field in self.__dict__ if not field.startswith('_')}

    result = {}
    for key in keys:
        if isinstance(key, int) and key < len(self.__dict__):
            result[self.__dict__.keys()[key]] = getattr(self, self.__dict__.keys()[key])
        elif isinstance(key, str) and hasattr(self, key):
            result[key] = getattr(self, key)
        elif isinstance(key, slice):
            result.update({field: getattr(self, field) for field in self.__dict__.keys() if field.startswith(self._prefix)})
            result.update({field[1:]: getattr(self, field) for field in self.__dict__.keys() if field.startswith(self._prefix + '_')})
        else:
            result[key] = None

