def pop_u16(self):
    """
    Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop_u16")
    byte1, byte2 = self.data[-2:]
    self.data = self.data[:-2]
    return (int.from_bytes(bytes1, byteorder='big') << 8) | int.from_bytes(bytes2, byteorder='big')

class Transaction:
    def __init__(self, mode=AccessMode.READ, bookmarks=None, metadata=None,
                 timeout=None, db=None, imp_user=None, dehydration_hooks=None,
                 hydration_hooks=None, **handlers):
        self.mode = mode
        self.bookmarks = bookmarks
        self.metadata = metadata
        self.timeout = timeout
        self.db_name = db
        self.imp_user = imp_user
        self dehydration_hooks = dehydration_hooks
        self.hydration_hooks = hydration_hooks
        self.handlers = handlers
        self.handlers[MessageType.BEGIN] = self._begin
        if_timeout = timeout is not None
        self._is_interrupted = False
        self._dbuf = None

    def _begin(self, msg):
        metadata = {}
        if self.bookmarks:
            metadata['bookmarks'] = list(self.bookmarks)
        if self.metadata:
            metadata.update(self.metadata)
        if self.db_name:
            metadata['db-name'] = self.db_name
        if self.imp_user:
            metadata['imp-user'] = self.imp_user
        self.producer.send(
            metadata,
            MessageType.BEGIN,
            msg.payload if msg else None,
            dehydration_hooks=self.dehydration_hooks,
            hydration_hooks=self.hydration_hooks,
        )
        if not if_timeout and msg.is_acknowledged():
            self.handle_complete_msg(msg)

    def handle_complete_msg(self, msg):
        if msg.is_complete():
            if hasattr(self, 'after_transaction') and callable(self.after_transaction):
                self.after_transaction()
            self.finish()

    def error(self, message):
        self.producer.send(
            {'error': message},
            MessageType.ERROR,
            msg.payload if msg else None,
            dehydration_hooks=self.dehydration_hooks,
            hydration_hooks=self.hydration_hooks,
        )
        if not hasattr(self, 'handle_error'):
            raise ValueError("Expected a handle_error function in transaction.")
        self.handle_error()

    def finish(self):
        if hasattr(self, 'finish'):
            self.finish()

    def abort(self):
        self.producer.send(
            {'error': 'Transaction aborted'},
            MessageType.ERROR,
            None,
            dehydration_hooks=self.dehydration_hooks,
            hydration_hooks=self.hydration_hooks,
        )
        if hasattr(self, 'before_transaction_aborted'):
            self.before_transaction_aborted()

    def stop(self):
        self.producer.stop()
        super(AbstractConsumer, self)._stop()

