    Rounding half to even with Python's built-in round function.

    :param n:
    :return:
    """
    # determine if the last digit is even or odd
    if int(abs(n) % 10) % 2 == 0:
        return round(n)
    # if the last digit is odd, add 0.5 to the number if it's positive or subtract 0.5 if it's negative
    else:
        return round(n + 0.5) if n >= 0 else round(n - 0.5)
