import warnings

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    Usage:

    @deprecated("'foo' has been deprecated in favour of 'bar'")
    def foo(x):
        pass

    """
    if not isinstance(message, str):
        raise ValueError("The message argument must be a string")

    @functools.wraps(deprecated)
    def _deprecate(func):
        a = func.__name__

        def wrapper(*args, **kwargs):
            warnings.simplefilter("always", DeprecationWarning)
            warnings.warn(a + " is deprecated, " + message, category=DeprecationWarning)
            return func(*args, **kwargs)

        return wrapper

    return wrapped if func is None else _deprecate(func)
