import time
from functools import wraps, lru_cache

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or not isinstance(ttl, int) or maxsize <= 0 or ttl <= 0:
        raise ValueError("maxsize and ttl must be positive integers")
    if not callable(timer):
        raise TypeError("timer must be a callable")

    class LRUWrapper:
        def __init__(self, func):
            self.func = func
            self.cache = lru_cache(maxsize=maxsize)(self._fetch_result)
            self.time_keys = {}
            self.now = None

        def reset(self):
            self.cache.clear()
            self.time_keys.clear()
            self.now = None

        def _fetch_result(self, key):
            if self.now is None:
                self.now = timer()
            ttl_key = (self.now + ttl, key)
            while ttl_key in self.time_keys:
                key, _ = self.time_keys.pop(ttl_key)
            self.time_keys[ttl_key] = key
            result = self.func(key)
            return result

        def __call__(self, *args, **kwargs):
            return self.cache(args, kwargs)

    def _delete_if_expired(key):
        if self.now is None:
            self.now = timer()
        ttl_key = (self.now + ttl * len(args) + (1 if typed else 0), key)
        while ttl_key in self.time_keys:
            del self.time_keys[ttl_key]
        return key

    def wrapper(func, timer=timer):
        return LRUWrapper(func)(timer=_delete_if_expired)

    return wrapper
