from functools import partial, wraps
from time import monotonic
import hashlib
from collections_abc import Mapping
from typing import Any, TypeVar, Callable, Tuple, Dict, Coroutine, Hashable

T = TypeVar('T')
Cache = Dict[Any, T]

class TTLCache(Mapping):
    def __init__(self, cache: Cache, maxsize: int, ttl: int, timer: Callable[[], float], typed: bool):
        self.cache = cache
        self.maxsize = maxsize
        self.ttl = ttl
        self.timer = timer
        self.keys = set()

    def __getitem__(self, key: Hashable) -> T:
        if key not in self.cache:
            raise KeyError(key)
        if self.timer() - self.cache[key][0] > self.ttl:
            del self.cache[key]
            raise KeyError(key)
        self.keys.add(key)
        return self.cache[key][1]

    def __setitem__(self, key: Hashable, value: T):
        self.cache[key] = (self.timer(), value)
        if len(self.cache) > self.maxsize:
            self.prune()
        self.keys.add(key)

    def __delitem__(self, key: Hashable):
        if key not in self.cache:
            raise KeyError(key)
        del self.cache[key]
        self.keys.discard(key)

    def __iter__(self) -> Iterator[Hashable]:
        return iter(self.keys)

    def __len__(self) -> int:
        return len(self.keys)

    def prune(self) -> None:
        now = self.timer()
        to_del = [k for k in self.keys if now - self.cache[k][0] > self.ttl]
        for k in to_del:
            del self.cache[k]
            self.keys.discard(k)

def ttl_cache(maxsize: int = 128, ttl: int = 600, timer: Callable[[], float] = monotonic, typed: bool = False) -> Callable[[Callable[T, T]], Callable[T, T]]:
    def decorator(func: Callable[T, T]) -> Callable[T, T]:
        fn = func
        if not inspect.isfunction(func):
            return functools.partial(ttl_cache, maxsize, ttl, timer, typed)(func)

        def wrapper(*args: Any, **kwargs: Any) -> T:
            key = functools.reduce(lambda x, y: hashlib.blake2b((str(x) + str(y)).encode()).hexdigest(), args, [])
            if key in cache:
                if timer() - cache[key][0] > ttl:
                    del cache[key]
                    return wrapper(*args, **kwargs)
                cache[key] = (timer(), wrapper(*args, **kwargs))
                return cache[key][1]
            value = fn(*args, **kwargs)
            cache[key] = (timer(), value)
            if len(cache) > maxsize:
                ttl_cache.prune(cache)
            return value

        cache = TTLCache({}, maxsize, ttl, timer, typed)
        wrapper.put = functools.partial(cache.__setitem__, key)
        wrapper.forget = functools.partial(cache.__delitem__, key)
        wrapper.clear = functools.partial(cache.__delitem__)
        return wrapper

    return decorator
