def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent

    :param classes: list of base classes
    :return: list of ordered minimum base classes
    """
    if not all(isinstance(cls, type) for cls in classes):
        raise TypeError("All elements must be classes")
    return sorted(classes, key=lambda cls: (cls.__name__, cls.__module__))

