import numpy as np

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if coord_name not in self.coords or coord_name not in self.data:
        raise ValueError("Coordinate '{:s}' is not available in the data".format(coord_name))

    coord = self.coords[coord_name]

    if not coord.is_monotonic:
        raise ValueError("Coordinate '{:s}' is not monotonic".format(coord_name))

    if coord.is_regular:
        err_indices = np.arange(coord.start, coord.stop, coord.step) - 1
    else:
        err_indices = np.arange(coord.start, coord.stop) - 1

    return err_indices.tolist()
