def _update_context(self,context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.

    """

    def add_error_context(subcontext, error_name):
        if error_name in subcontext:
            subcontext[error_name]['index'].append(self.index)
        else:
            subcontext[error_name] = {'index': [self.index]}

    # Example: Add error context for an error named "x_low"
    add_error_context(subcontext, 'x_low')

    # Update context properties
    if 'error' not in context:
        context['error'] = {}
    elif 'x_low' not in context['error']:
        context['error']['x_low'] = {'index': []}
    else:
        context['error']['x_low']['index'] += [self.index]

    # Assuming self.attributes is a dictionary containing graph properties
    for property_name, property_value in self.attributes.items():
        if property_name in context['value']:
            context['value'][property_name].update(property_value)
        else:
            context['value'][property_name] = property_value
