import copy
def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly. Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")

    if level == -1:
        result = copy.deepcopy(d1)
        for key in copy.deepcopy(result):
            if key in d2 and result[key] != d2[key]:
                result.pop(key)
        return result
    elif level == 0:
        result = {}
        for key in d1:
            if key not in d2:
                result[key] = d1[key]
        return result
    else:
        result = {}
        for key in d1:
            if key in d2 and isinstance(d1[key], dict) and isinstance(d2[key], dict):
                sub_result = difference(d1[key], d2[key], level - 1)
                if sub_result:
                    result[key] = sub_result
            elif key in d2 and key not in d1:
                result[key] = d2[key]
        return result
