from typing import Dict, List

class ValidationError(Exception):
    def __init__(self, messages: List[Dict[str, str]]):
        super().__init__("Validation errors occurred.")
        self.messages = messages

class InvalidFormat(ValueError):
    def __init__(self, error_message: str):
        super().__init__(error_message)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    messages = []
    for label, value in labels.items():
        if not isinstance(value, str):
            messages.append({"label": label, "value": "expected string or bytes-like object"})
        elif not value.match(cls.SUPPORTED_LABEL_FORMAT):
            formatted_data = {label: value}
            messages.append({"label": label, "value": formatted_data})
        elif value.isalnum():
            messages.append({"label": label, "value": "expected alphanumeric string"})
        elif re.match(cls.STARTSWITH_REGEXP, value) is None:
            messages.append({"label": label, "value": "should start with 'P'"})
        elif len(value) > 10:
            messages.append({"label": label, "value": "should be less than 10 characters"})
        elif any(char.isdigit() for char in value):
            messages.append({"label": label, "value": "should not contain numbers"})
        elif not isinstance(value, (int, float)):
            messages.append({"label": label, "value": "expected integer or float"})
    if messages:
        raise ValidationError(messages)
