def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if not isinstance(manifest_dict, dict):
        return None

    new = {}
    for key, value in manifest_dict.items():
        if isinstance(value, (list, tuple)):
            new[key] = [generate_default_observer_schema_dict(obj, first_level) for obj in value]
        elif isinstance(value, dict):
            new[key] = generate_default_observer_schema_dict(value, first_level)
        else:
            new[key] = None

        # Replace non-list and non-dict values by None
        if new[key] is None and key != 'type':
            new[key] = None

        # Copy identifying fields for first_level dictionary
        if first_level and key in ['metadata', 'spec']:
            new[key] = {
                k: v for k, v in manifest_dict['metadata'].items() if k in ['name', 'namespace', 'labels']
            }
            new[key].update(manifest_dict['spec'][k] if key in manifest_dict['spec'] else {})
    return new
