from typing import Dict, Optional

def generate_default_observer_schema_dict(
    manifest_dict: Dict, first_level: bool = False
) -> Dict:
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.
    """
    observer_schema = {}
    if first_level:
        for field in manifest_dict:
            if field in ["object_type", "object_id"]:
                observer_schema["id"] = manifest_dict[field]
            elif field == "source_attributes":
                observer_schema["sources"] = None  # We'll add sources later
            elif field == "actions":
                observer_schema["actions"] = None   # We'll add actions later
            elif field == "rules":
                observer_schema["rules"] = None   # We'll add rules later
            elif field == "status":
                observer_schema["status"] = None   # We'll add status later
            else:
                observer_schema[field] = None
    else:
        for field, value in manifest_dict.items():
            if isinstance(value, dict):
                observer_schema[field] = generate_default_observer_schema_dict(
                    value, first_level=False
                )
            elif isinstance(value, (list, tuple)):
                observer_schema[field] = []
                for item in value:
                    if isinstance(item, dict):
                        observer_schema[field].append(generate_default_observer_schema_dict(
                            item, first_level=False
                        ))
                    else:
                        observer_schema[field].append(item)
            else:
                observer_schema[field] = None
    return observer_schema
