from typing import Callable, AnyStr, Union, Iterable, Dict, List, Tuple

class SQLParams:
    in_style = "named"

def formatmany(
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    formatted_sql = sql
    converted_params = []
    for params in many_params:
        if hasattr(params, SQLParams.in_style):
            if isinstance(params, dict):
                converted_params.append(format_params(params, SQLParams.in_style))
            else:
                converted_params.append(format_params(params, SQLParams.in_style))
        else:
            converted_params.append(params)
            formatted_sql += ")"
    formatted_sql = formatted_sql.format(*converted_params)
    return formatted_sql, converted_params

def format_params(params: Dict[Union[str, int], Any], in_style: str) -> Dict[Union[str, int], Any]:
    if in_style == "named":
        return {param: value for param, value in params.items()}
    elif in_style == "ordinal":
        return list(params)
    else:
        raise ValueError("Unknown in-style parameter style")

