def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    @param indent: an integer value representing the number of spaces to use for indentation. Defaults to 0.
    @param debug: a boolean value indicating whether to add a debug print statement. Defaults to False.

    @return: a string representation of the object
    """
    parts = []
    indent_level = indent * ' ' * 4
    parts.append(f"{indent_level}{type(self).__name__}:\n")
    for attr in dir(self):
        value = getattr(self, attr)
        if not attr.startswith('__') and not attr.startswith('_'):
            parts.append(f"{indent_level}    {attr}: {value}\n")
    return '\n'.join(parts)
