def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def abs_or_not_arg(arg):
        import re
        exec_arg = 0
        if re.match(r'\^', arg):
            exec_arg = 1
            arg = arg[1:]
        tests = {}
        for test in arg.split('='):
            var_split = test.split()
            if len(var_split) > 1:
                var = var_split[1]
                tests[var] = var_split[0]
        return exec_arg, tests

    def apply_abs_opt(args):
        opt_list = []
        for arg in args:
            mod, tests = abs_or_not_arg(arg)
            if mod:
                opt_list.append("not")
            opt_list.append(arg.split('=')[0])
        return opt_list

    absorbing = True
    args_list = apply_abs_opt(args[:])

    if "not" in args_list:
        absorbing = not absorbing

    if not absorbing:
        neg_absorbing = True
    else:
        neg_absorbing = False

    expressions = []
    for arg in args_list:
        if not arg.startswith "!"):
            expressions.append(arg)
        else:
            expressions.append("not " + arg[1:])

    return expressions
