def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse

    parser = argparse.ArgumentParser()

    subparsers = parser.add_subparsers(dest='command')
    subparsers.add_parser('Generate', help='Generate a sample sheet based on a GEO series matrix.')
    subparsers.add_parser('Report', help='Report the execution status.')

    args = parser.parse_args(unparsed_arguments)

    result = {}
    for arg in args:
        if arg.startswith('--'):
            if arg.endswith('___'):
                key, value = arg[2:-3], True
            else:
                key, value = arg[2:], arg[3:].startswith('___')
            if key in result:
                if not isinstance(result[key], list):
                    result[key] = [result[key]]
                result[key].append(value)
            else:
                if value is False:
                    result[key] = False
                else:
                    result[key] = [value]

    return result
