import re

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not size:
        return 0

    size = size.upper()
    parts = re.split(r'(B|KB|MB|GB|TB|PB|EB|ZB|YB)', size)

    total_size = 0
    unit_factor = 1

    for part in parts:
        if 'B' in part:
            unit_factor = 1
        elif 'KB' in part:
            unit_factor = 1024
        elif 'MB' in part:
            unit_factor = 1024**2
        elif 'GB' in part:
            unit_factor = 1024**3
        elif 'TB' in part:
            unit_factor = 1024**4
        elif 'PB' in part:
            unit_factor = 1024**5
        elif 'EB' in part:
            unit_factor = 1024**6
        elif 'ZB' in part:
            unit_factor = 1024**7
        elif 'YB' in part:
            unit_factor = 1024**8

        try:
            value = float(part[:-1])
        except ValueError:
            return 0

        total_size += value * unit_factor

    return round(total_size, 2)
