        elif 'KB' in part:
            unit_factor = 1024
        elif 'MB' in part:
            unit_factor = 1024**2
        elif 'GB' in part:
            unit_factor = 1024**3
        elif 'TB' in part:
            unit_factor = 1024**4
        elif 'PB' in part:
            unit_factor = 1024**5
        elif 'EB' in part:
            unit_factor = 1024**6
        elif 'ZB' in part:
            unit_factor = 1024**7
        elif 'YB' in part:
            unit_factor = 1024**8

