def int_to_string(number, alphabet, padding=None):
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    min_length = max(0, abs(padding) if padding else 0)
    max_length = None if padding else len(alphabet) - 1
    if min_length > max_length:
        raise ValueError("padding is less than the length of alphabet")
    else:
        if padding:
            digits = [alphabet[number % len(alphabet)] for number in range(number, number - padding, -1)]
        else:
            digits = [alphabet[number % len(alphabet)] for number in range(number)]

        if min_length > 0:
            digits = list(reversed(digits[:min_length]))
        elif max_length is not None:
            digits = list(reversed(digits[max_length:]))

        else:
            digits = list(reversed(digits))

        return ''.join(digits)
