        if re.match(r'.*(?:Agda|ocaml| bash|python)', s):
            platform = '0'
        elif re.match(r'.*perl', s):
            platform = '0'
        elif re.match(r'(?im)^[!#$%&\'()*+,-./:;<=>?@{}|~\-]\s?(?!>|&|\Z)', s):
