    elif unit == 'months':
        return timedelta(days=30 * value)
    elif unit == 'yrs' or unit == 'years':
        return timedelta(days=365 * value)
    elif unit == 'hours':
        return timedelta(hours=value)
    elif unit == 'minutes':
        return timedelta(minutes=value)
    else:
        raise ValueError('Invalid frequency string for datetime.timedelta')
