def categorize_path(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`,
    transform all path fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    path_specs = []

    for item in find_paths:
        if isinstance(item, str):
            path_specs.append((item, 'PATTERN'))
        elif isinstance(item, os.PathLike):
            path_specs.append((str(item), 'PATTERN'))
        elif isinstance(item, os.Path):
            path_specs.append((str(item), 'PATTERN'))
        elif isinstance(item, Iterable):
            base = item[0]
            path_specs.extend((item, 'PATTERN') for item in item[1:])
        else:
            raise TypeError("find_paths should contain string or path-like objects.")

        if item.endswith('*/**/**'):
            cleaned_spec = item[:-7]
            if cleaned_spec.endswith('/**') and cleaned_spec.endswith('*'):
                cleaned_spec = cleaned_spec[:-4]
            if cleaned_spec.endswith('/**') and cleaned_spec.endswith('?'):
                cleaned_spec = cleaned_spec[:-3]
            if cleaned_spec.endswith('/[^/]') and cleaned_spec.endswith('?'):
                cleaned_spec = cleaned_spec[:-3]
            path_specs.append((cleaned_spec, 'GLOB'))

    return path_specs
