    args.insert(2, f"from importlib.machinery import ModuleSpec; from importlib.util import module_from_spec\n" 
                 f"spec = ModuleSpec('{func.__module__}', None)\ndef main(*args):\n    import sys\n    sys.modules['' + func.__name__] = spec.loader.exec_module(spec)\n    return {func.__name__}(*args)")
    if extra_env is not None:
        args.extend((f"{key}={value}" for key, value in extra_env.items()))
    result = subprocess.run(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, input=b'', timeout=timeout)
