class Graph:
    def __init__(self):
        self.nodes = {}
        self.parent_to_child = {}

    def add_edge(self, child: "Node", parent: "Node"):
        self.nodes[child].add(parent)
        if child not in self.parent_to_child:
            self.parent_to_child[child] = set()
        self.parent_to_child[child].add(parent)

    def get_children(self, node: "Node") -> Set["Node"]:
        return self.parent_to_child[node]

    def in_degree(self):
        count = {}
        for node, parents in self.parent_to_child.items():
            count[node] = len(parents)
        return count

    def get_node(self, id):
        return self.nodes[id]

def find_roots(graph: Graph, prop: rdflib.URIRef, roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if not roots:
        roots = set(graph.nodes.keys())
    todo = deque(roots)
    done = set(roots)

    while todo:
        node = todo.popleft()
        if node in done:
            continue

        parents = graph.get_parents(node)
        if not parents:
            done.add(node)
            continue

        not_done = parents - done
        if not not_done:
            # ALL PARENTS ARE PART OF A CYCLE, MAKE node A ROOT
            done.add(node)
            continue

        paths_from_roots = [
            list(reversed(graph.get_path_to_root(p)))
            for p in parents
        ]

        if any(p[0] is None for p in paths_from_roots):
            # THIS OBJECT CAN BE REACHED FROM A ROOT, IGNORE PATHS FROM LOOPS
            paths_from_roots = [p for p in paths_from_roots if p[0] is None]
            if len(paths_from_roots) == 1:
                # SHORTCUT
                dom = paths_from_roots[0][-1]
                done.add(node)
                continue

        # FIND COMMON PATH FROM root
        num_paths = len(paths_from_roots)
        for i, x in enumerate(zip_longest(*paths_from_roots)):
            if x.count(x[0]) != num_paths:
                dom = paths_from_roots[0][i-1]
                if dom is None:
                    # CAN BE REACHED FROM MORE THAN ONE LOOP, PICK ONE TO BLAME
                    dom = paths_from_roots[0][-1]
                break
        else:
            # ALL PATHS IDENTICAL
            dom = paths_from_roots[0][-1]

        done.add(node)
        todo.extend(prv for prv in parents)

    return done
