def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if not hasattr(graph, "triples"):
        raise ValueError("Graph object must have a 'triples' method.")

    if not isinstance(prop, rdflib.URIRef):
        raise ValueError("Prop must be a URIRef.")

    if roots is None:
        roots = set()

    for subject, predicate, object in graph.triples((None, prop, None)):
        if predicate == rdflib.RDFS.subClassOf and object not in roots:
            roots.add(object)
            if object not in graph.subjects(object, rdflib.RDFS.subClassOf):
                find_roots(graph, rdflib.RDFS.subClassOf, roots)

    return roots
