import yaml

def _dump_string(obj, dumper=None):
    """
    Dump to a py2-unicode or py3-string
    """
    # helper to generate a dictionary from a python object
    def yamlize(pyobj):
        return mappings_to_yaml(yamlize) if isinstance(pyobj, dict) else pyobj

    # recursively convert list and set items to pass sanity to yaml lib
    def mappings_to_yaml(elements):
        return {yamlize(key): yamlize(value) for key, value in elements if value is not None}

    # convert python object into a dumpable string
    try:
        return yaml.safe_dump(obj, stream=None, dumper=dumper)
    except TypeError:
        # fall back to str on encode bytestring
        return obj.decode('utf-8')


