def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    import sys

    if isinstance(seq, str):
        if bufsize is None:
            bufsize = sys.maxsize
        return (seq.encode(sys.getdefaultencoding(), "surrogateescape"), "str")
    elif isinstance(seq, bytes):
        # Convert bytes to str if needed, before returning the sequence and type
        return (seq.decode(sys.getdefaultencoding(), "surrogateescape"), "bytes")
    elif isinstance(seq, (int, float)):
        # Convert numeric types to str if needed, before returning the sequence and type
        return (str(seq), type(seq))
    elif isinstance(seq, tuple) or isinstance(seq, list):
        # If the sequence is already a tuple or list, return it as is
        if isinstance(seq, tuple):
            return (seq, type(seq))
        elif isinstance(seq, list):
            return (tuple(seq), type(seq))
    else:
        # Return the sequence and its type if none of the above cases match
        return (seq, type(seq))
