import numpy as np

class Scaling:
    def __init__(self):
        self.scales = {}
        self.scales_metadata = {}

    def _reset(self):
        self.scales.clear()
        self.scales_metadata.clear()

    def fit(self, X, y=None):
        """
        Compute the mean and standard deviation from a dataset to use in future scaling operations.

        :param X: Data matrix to scale.
        :type X: numpy.ndarray, shape [n_samples, n_features]
        :param y: Passthrough for Scikit-learn ``Pipeline`` compatibility.
        :type y: None
        :return: Fitted object.
        :rtype: pyChemometrics.ChemometricsScaler
        """
        # Reset internal state before fitting
        self._reset()
        return self.partial_fit(X, y)

    def _get_dimension_scales(self, dimension, preserve_domain=False):
        """
        Return the list of scales corresponding to a given dimension.

        The preserve_domain optional argument specifies whether one should
        filter out the scales for which preserve_domain is set to True.
        """
        if preserve_domain:
            return [
                self.scales[k] for k in self.scales if (
                    k in self.scales_metadata and
                    self.scales_metadata[k].get('dimension') == dimension and
                    not self.preserve_domain.get(k)
                )
            ]
        else:
            return [
                self.scales[k] for k in self.scales if (
                    k in self.scales_metadata and
                    self.scales_metadata[k].get('dimension') == dimension
                )
            ]

    def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        if other is None:
            return self.scale_x()
        else:
            return self.scale_x(new_value=other)

    def scale_x(self, new_value=None):
        if not hasattr(self, 'scale_x') or new_value is None:
            raise LenaValueError("The graph's scale_x attribute must be set.")

        # Get the current scale
        scale_x = self.scale_x

        if new_value is not None:
            # Update the scale with the new value
            self.scale_x = new_value
            return new_value

        # Rescale all coordinates along the x-axis
        self.x = self.x / scale_x
        return scale_x
