from zope.interface import Invalid
from inspect import isfunction, ismethod, getmembers

def verifyObject(iface, candidate, tentative=False):
    if tentative:
        claims = candidate.providedBy(iface)
        provides = candidate.implementedBy or candidate.provides(iface)
    else:
        claims = iface.providedBy(candidate)
        provides = candidate.implementedBy or candidate.provides(iface)

    if not claims:
        raise Invalid(f"{candidate} does not provide {iface}")

    methods = getmembers(candidate, predicate=inspect.isfunction)
    if methods and not tentative:
        for method, description in methods:
            if not inspect.signature(method).fnmatch(iface.allMethods()):
                raise Invalid(f"Method {method} does not match {iface}的所有方法")

    attributes = getmembers(candidate, predicate=inspect.isdatadescriptor)
    if attributes and not tentative:
        for attribute in attributes:
            if not isinstance(attribute[1], iface.allAttributes()):
                raise Invalid(f"Attribute {attribute[0]} does not match {iface}的所有属性")

    return True
