class Dictator:
    def __init__(self):
        self._dict = dict()
        self._freq = Counter()
        self._head = [None, None, None]
        self._tail = [None, None, None]

    def _find_less_freq(self, node):
        cur = self._head
        while cur[2] != node:
            cur = cur[2]
        less_freq = self._heapq_nlargest(1, self._freq.keys(), key=self._freq.get)
        return less_freq[0] if less_freq else None

    def _remove(self, node):
        self._links(node[2], node[3])
        del self._dict[node[0]]

    def _links(self, pre, nxt):
        if pre[2] is not None:
            pre[2][3] = nxt
        if nxt[2] is not None:
            nxt[2][3] = pre
        self._freq[node[0]] -= 1
        if self._freq[node[0]] == 0:
            del self._freq[node[0]]

    def popitem(self) -> Tuple[Any, Any]:
        """Remove and return the `(key, value)` pair least frequently used."""
        if self._head[2] is None:
            raise KeyError('list is empty')
        node = self._head[2]
        less_freq_key = self._find_less_freq(node)
        if less_freq_key is None:
            # If no less frequent key exists, simply remove the head of the list
            self._remove(self._head)
        else:
            self._dict.pop(less_freq_key)
            self._freq[less_freq_key] -= 1
            if self._freq[less_freq_key] == 0:
