from typing import Tuple, Set, Any, Callable

def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    tag_pattern = re.compile(r'#\s*([a-zA-Z0-9-_]+)')
    tags = set()

    def remove_code_block_tag(match):
        markup_start = match.group(1)
        markup_end = match.group(2)
        if markup_start == markup_end:
            return match.group(0)
        return match.group(0).strip(markup_start) + match.group(0).strip(markup_end)

    cleaned_text = re.sub(r'#\s*{codeblock:\s*.*?\s*}', remove_code_block_tag, text)

    for tag_match in tag_pattern.finditer(cleaned_text):
        tag = tag_match.group(1)
        if replacer:
            cleaned_text = cleaned_text.replace(tag_match.group(0), replacer(tag))
        tags.add(tag)

    return tags, cleaned_text
