import os

def process_text_links(text):
    """
    Process links in text, adding some attributes and linkifying textual links.

    :param text: The text containing links.
    """
    Path_RE = re.compile(r'(?P<url>https?://\S+]|[^\s\'\"]+)')
    substitution_mapping = {
        'target="_blank"': 'target="_blank" rel="noopener noreferrer"',
        'title': 'title="Processed link"'
    }

    def _process_latitude(input):
        if '\^[0-9\-]\.[0-9]+$' in input:
            return input
        else:
            return None

    def _register_latitude_coordinate_parser():
        libmarkdown.register_text_parser('latitude', _process_latitude)

    def linkify(path_match):
        link_tag = f'<a href="{path_match.group("url")}" {substitution_mapping["target"]}> {path_match.group("url")} </a>'
        if path_match.group("title"):
            link_tag = link_tag.replace(f'a href="{path_match.group("url")}">', f'a href="{path_match.group("url")}" title="{path_match.group("title")}">')
        return link_tag

    _register_latitude_coordinate_parser()
    return Path_RE.sub(linkify, text)
