from urllib.request import UrlLib2HeadRequest
from urllib.parse import urlparse
import urllib.error
from typing import Optional


def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""

    if not url or not urlparse(url).scheme in ('http', 'https'):
        return None

    try:
        req = UrlLib2HeadRequest(url, headers={'Host': urlparse(url).netloc})
        resp = urlopen(req)
        if resp.getcode() != 200:
            return None
        return resp.info().get('content-type', None)
    except urllib.error.URLError:
        return None
    finally:
        if resp:
            resp.close()
