                    for key, value in default_dict.items():
                        if issubclass(value.type, str):
                            spec_defaults[key] = value.value
        # Retrieve other source defaults
        other_sources = self.source.get_defaults()
        for key, value in other_sources.items():
            if spec_defaults.get(key) is None:
                spec_defaults[key] = value
    except Exception as e:
        raise Exception(f"Failed to resolve defaults: {e}")
    return spec_defaults

