def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """

    # First, apply default values from config
    spec_defaults = self.spec.defaults

    # If there are not spec defaults, attempt to get them from scheme
    if not spec_defaults:
        try:
            spec_defaults = self.scheme.build_defaults()
        except errors.InvalidSchemeError:
            spec_defaults = {}

    # Delegate further resolution to other bases or sources
    base_defaults = self.delegate_get_specs_defaults()
    defaults = {**spec_defaults, **base_defaults}

    return defaults
