def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra_vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    else:
        for key, value in extra_vars.items():
            if key in vars_dict:
                # If the key already exists, values can be lists (considering them as sets)
                if isinstance(vars_dict[key], list) and isinstance(value, list):
                    vars_dict[key].extend(value)
                else:
                    vars_dict[key] = list(set(vars_dict[key]).union(set([value])))
            else:
                vars_dict[key] = value
        return vars_dict
