        self.plugin_dir = plugin_dir

    def get_plugin_spec_flatten_dict(self) -> Dict[str, Any]:
        flatten_dict = {}
        for root, dirs, files in os.walk(self.plugin_dir):
            relative_dirs = [os.path.relpath(d, root) for d in dirs]
            file_paths = [os.path.relpath(f, root) for f in files]

            for relative_dir in relative_dirs:
                if relative_dir.startswith('layers'):
                    for prefix in file_paths:
                        if relative_dir[-len(prefix):] == prefix:
                            flatten_dict[relative_dir] = prefix
                            break

            for file_path in file_paths:
                if file_path.startswith('Layers'):
                    relative_file = os.path.relpath(file_path, root)
                    for dirver in flatten_dict.keys():
                        if relative_file.startswith(dirver):
                            if '/' in relative_file:
                                flatten_dict[dirver] += '_' + relative_file.split('/')[-1]
