from collections import defaultdict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_dict = defaultdict(str)
    for root, dirs, files in walk(plugin_dir):
        for file_name in files:
            if file_name.endswith('.py'):
                with open(f'{root}/{file_name}', 'r') as file:
                    contents = file.read()
                    for attr_name, attr_value in inspect.getmembers(file, lambda x: not callable(x) and not x.__name__.startswith('__')):
