def strip_root(path, root):
    """
    Remove root from path, throw exception on failure."""

    try:
        stripped_path = path.replace(root, '', 1)
        if stripped_path == '' or stripped_path == root:
            raise ValueError("Path does not contain the root.")
        return stripped_path
    except ValueError as error:
        raise foundations.exceptions.StripRootError(
            "!> {0} | Cannot strip root from path: '{1}'. {2}".format(__name__, path, error))
